fluent.css:
/* main menu items */
  :not(:not(menubar) > menu, #ContentSelectDropdown)>menupopup>menuitem:not(.menuitem-iconic,
    [type="checkbox"],
    [type="radio"],
    .in-menulist,
    .in-menulist menuitem,
    .unified-nav-current),
  menupopup>menu:not(.menu-iconic,
    [type="checkbox"],
    [type="radio"],
    .in-menulist,
    .in-menulist menu,
    .unified-nav-current),
  #toggle_toolbar-menubar,
  #PanelUI-history toolbarbutton,
  #unified-extensions-context-menu {
    background-image: var(--menu-image) !important;
    background-size: 16px !important;
    background-position: var(--fp-contextmenu-menuitem-padding-inline) center !important;
    background-repeat: no-repeat !important;
    -moz-context-properties: fill, fill-opacity !important;
    fill: currentColor !important;
  }
/* sub menu items */
  #context_reopenInContainerPopupMenu>menuitem:not(.menuitem-iconic,
    [type="checkbox"],
    [type="radio"],
    .in-menulist,
    .in-menulist menuitem,
    .unified-nav-current),
  menuitem.sine-moved,
  menuitem[id$="-sine-clone"],
  menuitem[class*="sine"],
  #context_zenWorkspacesOpenInContainerTab>menupopup>menuitem:not(.menuitem-iconic,
    [type="checkbox"],
    [type="radio"],
    .in-menulist,
    .in-menulist menuitem,
    .unified-nav-current) {
    background-image: var(--menu-image) !important;
    background-size: 16px !important;
    background-position: var(--fp-contextmenu-menuitem-padding-inline) center !important;
    background-repeat: no-repeat !important;
    -moz-context-properties: fill, fill-opacity !important;
    fill: currentColor !important;
  }

